// Helper functions to calculate expected values
function lineTotal(qty, unitPrice) { return qty * unitPrice; }
function discountAmount(qty, unitPrice, discountPercent = 0) {
  const lt = lineTotal(qty, unitPrice);
  const firstDiscount = Math.round(lt * discountPercent / 100);
  const bulkDiscount = qty >= 10 ? Math.round((lt - firstDiscount) * 0.025) : 0;
  return firstDiscount + bulkDiscount;
}
function lineVAT(qty, unitPrice, vatRate, discountPercent = 0) {
  const lt = lineTotal(qty, unitPrice);
  const discount = discountAmount(qty, unitPrice, discountPercent);
  return Math.round((lt - discount) * vatRate / 100);
}

// Test: single line qty 5
const t1_total = lineTotal(5, 9500);
const t1_discount = discountAmount(5, 9500, 0);  // C-001 gold tier will add 5% in invoice creation
const t1_vat = lineVAT(5, 9500, 21, 0);
console.log('Single line (qty 5):', { subtotal: t1_total, discount: t1_discount, vat: t1_vat });

// With tier discount
const t1_tier_discount = Math.round(t1_total * 0.05);  // 5% tier
const t1_tier_vat = Math.round((t1_total - t1_tier_discount) * 0.21);
console.log('Single line with tier 5%:', { subtotal: t1_total, discount: t1_tier_discount, vat: t1_tier_vat, total: t1_total - t1_tier_discount + t1_tier_vat });
EOF
